use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        if arr.is_empty() {
            return Value::Null;
        }

        let mut counts = vec![0; 256];
        for item in arr {
            if let Value::String(s) = item {
                for c in s.chars() {
                    counts[c as usize] += 1;
                }
            }
        }

        let mut most_frequent = Value::Null;
        let mut max_count = 0;

        for &count in &counts {
            if count > max_count || (count == max_count && most_frequent.is_null() || count > most_frequent.as_i64().unwrap()) {
                most_frequent = Value::String(item.as_str().unwrap());
                max_count = count;
            }
        }

        most_frequent
    } else {
        Value::Null
    }
}
